// This file is generated by AI.

// 角色列表: 管理 GSOV 模型 + 参考音频组合。
//
// 列表本身**只展示信息**, 不提供任何就地编辑, 也没有针对单个角色的操作按钮 ——
// 一行里塞满输入框与按钮会造成很大的认知压力。所有编辑都在「编辑角色」对话框里
// 完成 (点卡片即打开); 导出与删除在「选择角色」对话框里。

import { Button, Input } from '@fluentui/react-components';
import { AddRegular, PersonEditRegular, StarFilled } from '@fluentui/react-icons';
import { useEffect, useMemo, useState } from 'react';

import type { Character, ModelCandidate } from '../commands/voice';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { RoleEditDialog } from './RoleEditDialog';
import { RolePickerDialog } from './RolePickerDialog';

export function RoleListPanel() {
  const characters = useAppStore((state) => state.voiceCharacters);
  useAppStore((state) => state.voiceTick);
  const [query, setQuery] = useState('');
  const [pickerOpen, setPickerOpen] = useState(false);
  const [editTarget, setEditTarget] = useState<Character | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [models, setModels] = useState<ModelCandidate[]>([]);

  useEffect(() => {
    voiceController.primeReferencePaths().catch(() => {});
  }, [characters.length]);

  // 扫描整合包内的 v4 权重, 为角色的模型下拉提供候选
  useEffect(() => {
    void voiceController.listModels().then(setModels);
  }, [characters.length]);

  const enabled = useMemo(
    () => characters.filter((character) => character.enabled && matchesQuery(character, query)),
    [characters, query]
  );

  const create = async () => {
    setError(null);
    try {
      const created = await voiceController.createCharacter(`新角色 ${characters.length + 1}`, '');
      // 新建后直接打开编辑对话框, 否则用户看不到自己刚建了什么
      setEditTarget(created);
      setQuery('');
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    }
  };

  /**
   * 「选择角色」= 打开挑选对话框。
   *
   * **不要先清空**: 曾经这里在打开对话框前把所有角色取消勾选 ("先清空再挑"),
   * 结果是对话框里一个都没勾 (用户看到的正是"里面没有选中的"), 而只要不进对话框
   * 挨个勾回来, 关掉它就会让**所有手动指定的角色一起失效** —— 侧边栏与场景卡里的
   * 归属都变成未选择。勾选状态本来就是对话框的内容, 直接打开、原样显示即可。
   */
  const openPicker = () => {
    setError(null);
    setPickerOpen(true);
  };

  /** 打开编辑对话框时始终取最新的一份角色数据 */
  const openEditor = (id: string) => {
    const latest = useAppStore.getState().voiceCharacters.find((item) => item.id === id) ?? null;
    setEditTarget(latest);
  };

  return (
    <div className="character-panel">
      <div className="character-toolbar">
        <Input
          className="character-search"
          placeholder="搜索角色…"
          value={query}
          onChange={(_, data) => setQuery(data.value)}
        />
        <Button appearance="primary" icon={<AddRegular />} onClick={() => void create()}>
          新建角色
        </Button>
        {/*
          「选择角色」直接打开挑选对话框, 对话框里显示的就是当前勾选状态;
          在里面改一个就生效一个, 什么都不改地关掉则一切照旧。任何情况下都**不禁用**:
          一个永远可点的入口比一个灰掉的按钮好懂得多。
        */}
        <Button appearance="secondary" icon={<PersonEditRegular />} onClick={openPicker}>
          选择角色
        </Button>
      </div>

      {error && <p className="voice-error">{error}</p>}

      <div className="character-list">
        {characters.length === 0 && (
          <p className="voice-dialog-empty">还没有角色。先「新建角色」或导入一份角色配置。</p>
        )}
        {characters.length > 0 && enabled.length === 0 && (
          <p className="voice-dialog-empty">没有已启用的角色。点「选择角色」勾选需要参与配音的角色。</p>
        )}
        {enabled.map((character) => (
          <div key={character.id} className="character-tile">
            <button
              type="button"
              className="character-tile-main"
              title="点击编辑角色"
              onClick={() => openEditor(character.id)}
            >
              <span className="character-tile-name">
                {character.name}
                {character.starred && <StarFilled className="character-tile-star" />}
              </span>
              <span className="character-tile-meta">
                {character.id} · 参考音频 {character.references.length}
                {character.description.trim() && ` · ${character.description.trim()}`}
              </span>
              <span className="character-tile-models">
                <span className="character-tile-model" title={character.model?.gptWeights ?? '未指定'}>
                  GPT {suffixOf(character.model?.gptWeights)}
                </span>
                <span className="character-tile-model" title={character.model?.sovitsWeights ?? '未指定'}>
                  SoVITS {suffixOf(character.model?.sovitsWeights)}
                </span>
              </span>
            </button>
          </div>
        ))}
      </div>

      <RolePickerDialog open={pickerOpen} onClose={() => setPickerOpen(false)} onError={setError} />

      {editTarget && (
        <RoleEditDialog
          character={editTarget}
          models={models}
          onClose={() => setEditTarget(null)}
          onChanged={() => {
            const latest = useAppStore.getState().voiceCharacters.find((item) => item.id === editTarget.id);
            setEditTarget(latest ?? null);
          }}
          onError={setError}
        />
      )}
    </div>
  );
}

function matchesQuery(character: Character, query: string): boolean {
  if (!query.trim()) return true;
  const needle = query.trim().toLowerCase();
  return character.name.toLowerCase().includes(needle) || character.id.toLowerCase().includes(needle);
}

/** 权重路径的可读后缀 (只取文件名) */
function suffixOf(weights: string | null | undefined): string {
  if (!weights) return '未指定';
  return weights.replace(/\\/g, '/').split('/').pop() ?? weights;
}
